"""wp82 item 5: end gateways without an exit at many entry points, the exit each server saved (the chunks of the outer islands are generated by the trip). usage: gwbatch82.py x,z x,z ..."""
from lab import *
E = "execute in minecraft:the_end run "
pts = [tuple(int(v) for v in a.split(",")) for a in sys.argv[1:]]
for t in "KV":
    w(t, "gamemode creative W0"); w(t, "gamerule spawn_mobs false")
    w(t, E + "forceload add -64 -64 64 64")
    w(t, E + "tp W0 0.5 130 0.5")
time.sleep(12)
for (x, z) in pts:
    for t in "KV":
        w(t, E + f"setblock {x} 80 {z} minecraft:end_gateway")
        w(t, E + f"summon cow {x}.5 80 {z}.5 {{NoAI:1b,PersistenceRequired:1b,Tags:[\"gb\"]}}")
    time.sleep(7)
    out = {}
    for t in "KV":
        o = ask(t, E + f"data get block {x} 80 {z}", wait=0.4)
        m = re.search(r"exit_portal: \[I; (-?\d+), (-?\d+), (-?\d+)\]", o)
        out[t] = tuple(int(g) for g in m.groups()) if m else None
        w(t, E + "kill @e[tag=gb]")
    F((x, z), "SAME" if out["K"] == out["V"] else "DIFF", out)
